use super::geometry::Point;

#[derive(Clone, Copy)]
struct Node {
    index: u32,
    point: Point,
    prev: usize,
    next: usize,
    removed: bool,
}

pub fn triangulate(points: &[Point]) -> Vec<u32> {
    if points.len() < 3 || signed_area(points) <= 0.0 {
        return Vec::new();
    }

    let mut nodes = Vec::with_capacity(points.len());
    for (index, point) in points.iter().copied().enumerate() {
        let prev = if index == 0 { points.len() - 1 } else { index - 1 };
        let next = if index + 1 == points.len() { 0 } else { index + 1 };
        nodes.push(Node {
            index: index as u32,
            point,
            prev,
            next,
            removed: false,
        });
    }

    let mut triangles = Vec::with_capacity((points.len() - 2) * 3);
    let mut remaining = points.len();
    let mut ear = points.len() - 1;
    let mut stop = ear;

    while remaining > 2 {
        if is_ear(&nodes, ear) {
            let prev = nodes[ear].prev;
            let next = nodes[ear].next;
            triangles.push(nodes[prev].index);
            triangles.push(nodes[ear].index);
            triangles.push(nodes[next].index);

            remove_node(&mut nodes, ear);
            remaining -= 1;

            ear = nodes[next].next;
            stop = ear;
            continue;
        }

        ear = nodes[ear].next;
        if ear == stop {
            break;
        }
    }

    triangles
}

fn signed_area(points: &[Point]) -> f64 {
    let mut area = 0.0;
    for index in 0..points.len() {
        let next = (index + 1) % points.len();
        area += points[index].x * points[next].y - points[next].x * points[index].y;
    }
    area * 0.5
}

fn is_ear(nodes: &[Node], ear: usize) -> bool {
    if nodes[ear].removed {
        return false;
    }

    let prev = nodes[ear].prev;
    let next = nodes[ear].next;
    let a = nodes[prev].point;
    let b = nodes[ear].point;
    let c = nodes[next].point;

    if orient(a, b, c) <= 0.0 {
        return false;
    }

    let mut probe = nodes[next].next;
    while probe != prev {
        if !nodes[probe].removed && point_in_triangle(a, b, c, nodes[probe].point) {
            return false;
        }
        probe = nodes[probe].next;
    }

    true
}

fn point_in_triangle(a: Point, b: Point, c: Point, p: Point) -> bool {
    orient(a, b, p) >= 0.0 && orient(b, c, p) >= 0.0 && orient(c, a, p) >= 0.0
}

fn orient(a: Point, b: Point, c: Point) -> f64 {
    (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x)
}

fn remove_node(nodes: &mut [Node], ear: usize) {
    let prev = nodes[ear].prev;
    let next = nodes[ear].next;

    nodes[prev].next = next;
    nodes[next].prev = prev;
    nodes[ear].removed = true;
}

